-- =====================================================================================
--  P48-أ — «ملف الاعتماد الحيّ» (الرسمي: ملف الدراسة الذاتية للاعتماد البرامجي — متجدِّد)
--   1) portal_accred_standards: إطاران مرجعيان قابلان للتعديل من الإدارة بلا نشر كود:
--      pas = معايير الاعتماد البرامجي لبرامج التدريب المنتهية بمؤهل (هيئة تقويم التعليم والتدريب · 4 معايير / 21 فرعيًّا — نصّ المشروع على منصّة استطلاع؛ أُطلق 2025-11-02)
--      tps = المعايير المهنية للمعلمين (3 مجالات بأوزانها 21/40/39 · 10 معايير عامة · 21 فرعيًّا)
--   2) portal_accred_narratives: فقرة الدراسة الذاتية لكل (برنامج · إطار · معيار) — لا تُحفظ إلا موقَّعة من إنسان، مع معرّفات الأدلة التي بُنيت عليها.
--   3) portal_accred_skill_maps: خريطة كفايات البرنامج → معايير المعلّم العامة (لبرامج إعداد المعلّمين).
--  الأدلة نفسها لا تُنسخ (تُجمَع عند الطلب من الجداول المعتمَدة). آمن لإعادة التنفيذ.
-- =====================================================================================
create table if not exists public.portal_accred_standards (
  framework   text not null check (framework in ('pas','tps')),
  code        text not null,
  parent      text,
  title_ar    text not null,
  text_ar     text not null,
  weight      numeric,
  sort        int  not null default 0,
  source      text not null default 'official' check (source in ('official','draft')),
  active      boolean not null default true,
  updated_at  timestamptz not null default now(),
  updated_by  uuid,
  primary key (framework, code)
);
alter table public.portal_accred_standards enable row level security;
drop policy if exists portal_accred_standards_read on public.portal_accred_standards;
create policy portal_accred_standards_read on public.portal_accred_standards for select to anon, authenticated using (true);   -- نصوص المعايير عامة
revoke insert, update, delete on public.portal_accred_standards from anon, authenticated;

create table if not exists public.portal_accred_narratives (
  id           uuid primary key default gen_random_uuid(),
  program_id   uuid not null references public.programs(id) on delete cascade,
  framework    text not null check (framework in ('pas','tps')),
  code         text not null,
  text_ar      text not null,
  evidence_ids jsonb not null default '[]'::jsonb,
  signed_by    uuid,
  signed_name  text,
  signed_at    timestamptz,
  source       text not null default 'human' check (source in ('human','local','ai')),
  updated_at   timestamptz not null default now(),
  unique (program_id, framework, code)
);
create index if not exists portal_accred_narratives_program_idx on public.portal_accred_narratives (program_id);
alter table public.portal_accred_narratives enable row level security;
drop policy if exists portal_accred_narratives_read on public.portal_accred_narratives;
create policy portal_accred_narratives_read on public.portal_accred_narratives for select to authenticated using (true);   -- القراءة لمن سجّل دخوله؛ الخادم يقيّد العرض بنطاق البرنامج
revoke insert, update, delete on public.portal_accred_narratives from anon, authenticated;

create table if not exists public.portal_accred_skill_maps (
  program_id  uuid primary key references public.programs(id) on delete cascade,
  map         jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
alter table public.portal_accred_skill_maps enable row level security;
drop policy if exists portal_accred_skill_maps_read on public.portal_accred_skill_maps;
create policy portal_accred_skill_maps_read on public.portal_accred_skill_maps for select to authenticated using (true);
revoke insert, update, delete on public.portal_accred_skill_maps from anon, authenticated;

-- البذر (لا يكتب فوق تعديلات الإدارة: on conflict do nothing)
insert into public.portal_accred_standards (framework, code, parent, title_ar, text_ar, weight, sort) values
  ('pas', '1', null, 'تصميم وتطوير البرنامج', 'يتوافق البرنامج مع متطلبات الإطار الوطني للمؤهلات، وتتسق أهداف البرنامج ونواتج التعلم مع الاحتياجات التنموية وسوق العمل، وتتضمن عملية التصميم والتطوير مشاركة فاعلة لأصحاب المصلحة وجهات العمل.', null, 10),
  ('pas', '1.1', '1', 'البيانات الوصفية ونواتج التعلم', 'تتوافق البيانات الوصفية للبرنامج (اسم المؤهل والمستوى ومجال التخصص، والحد الأدنى للساعات (الوحدات التدريبية) المعتمدة، وعدد السنوات الدراسية)، ونواتج التعلم مع اشتراطات الإطار الوطني للمؤهلات والمعايير المهنية والتخصصية المعتمدة في مجال التخصص.', null, 11),
  ('pas', '1.2', '1', 'الشراكة مع أصحاب المصلحة', 'يُطبّق البرنامج منهجية فاعلة للشراكة مع أصحاب المصلحة وجهات العمل لتحديد متطلباتهم الحالية وتوقعاتهم المستقبلية عند تصميم وتطوير البرنامج، ويستفاد من هذه الشراكة في تطوير البرنامج.', null, 12),
  ('pas', '1.3', '1', 'مصادر التعلم والمرافق', 'يحدد البرنامج مصادر التعلم والمرافق والتجهيزات اللازمة لتحقيق أهدافه، ويتضمن منهجية واضحة لمتابعة استخدامها وتحديثها بمشاركة أصحاب المصلحة.', null, 13),
  ('pas', '1.4', '1', 'المحتوى التدريبي', 'يراعي المحتوى التدريبي تحقيق أهداف البرنامج ونواتج التعلم والتطورات العلمية والتقنية والمهنية في مجال التخصص، ويخضع إعداده وتطويره لقيم الأمانة العلمية وحقوق الملكية الفكرية.', null, 14),
  ('pas', '1.5', '1', 'إستراتيجيات التدريب', 'يحدد البرنامج إستراتيجيات التدريب المناسبة لتحقيق نواتج تعلم البرنامج، بما في ذلك متطلبات التدريب التعاوني و/أو التدريب على رأس العمل و/أو التلمذة المهنية.', null, 15),
  ('pas', '1.6', '1', 'قياس نواتج التعلم', 'يحدد البرنامج الآليات والأدوات المناسبة لقياس نواتج التعلم والتحقق من استيفائها وفق مستويات أداء وخطط تقييم محددة.', null, 16),
  ('pas', '2', null, 'تقويم وجودة البرنامج', 'يُطبّق البرنامج إستراتيجيات التدريب وطرق التقويم المناسبة والمتنوعة لتحقيق نواتج التعلم وقياسها، وتُستخدم نتائج التقويم والتقارير الدورية في تحسين وتطوير البرنامج.', null, 20),
  ('pas', '2.1', '2', 'إستراتيجيات التدريب ونتائج التقويم', 'يُطبّق البرنامج إستراتيجيات تدريب متنوعة لتحقيق أهدافه العامة والتخصصية، ويستفاد من نتائج التقويم والتقارير الدورية في تطوير البرنامج.', null, 21),
  ('pas', '2.2', '2', 'أدوات التقويم والإجراءات التصحيحية', 'يُطبّق البرنامج أدوات تقويم متنوعة ومناسبة تقيس مستوى تقدم المتدربين في تحقيق نواتج التعلم، وتتخذ الإجراءات التصحيحية للرفع من تحصيلهم وفقاً لنتائج التقويم.', null, 22),
  ('pas', '2.3', '2', 'الموارد والتجهيزات', 'يستخدم البرنامج الموارد والتجهيزات اللازمة لتنفيذ التدريب (بما في ذلك الموارد التقنية) بفاعلية، ويقوم بتحديثها بصورة منتظمة، ويتابع طرق ومدى استخدامها وتتخذ الإجراءات التصحيحية وفقًا لذلك.', null, 23),
  ('pas', '2.4', '2', 'التدريب التعاوني وعلى رأس العمل', 'يتحقق البرنامج من فعالية التدريب التعاوني و/أو التدريب على رأس العمل و/أو التلمذة المهنية في تحقيق أهدافه ونواتج التعلم المستهدفة، ويستفاد من النتائج والتقارير في تطوير البرنامج.', null, 24),
  ('pas', '2.5', '2', 'مؤشرات الأداء واستطلاعات المستفيدين', 'تُستخدم مؤشرات الأداء واستطلاعات أصحاب المصلحة والمستفيدين في تقويم ومراجعة البرنامج وجودة مخرجاته، وتُستخدم النتائج لتطوير وتحسين البرنامج.', null, 25),
  ('pas', '2.6', '2', 'التقويم الذاتي والمراجعة', 'يُطبّق البرنامج آليات واضحة ومنتظمة لتقويم ومراجعة البرنامج (بما في ذلك التقويم الذاتي، المراجعة الخارجية)، ويستفاد من النتائج والتقارير في تحسين وتطوير البرنامج.', null, 26),
  ('pas', '3', null, 'المتدربون', 'يقدم البرنامج خدمات الدعم والتوجيه والإرشاد لمتدربي البرنامج لرفع معدلات إكمالهم واستبقائهم، وتنمية ومواءمة مهاراتهم مع متطلبات سوق العمل وتعزيز تعلمهم، ومتابعة إجراءات توظيفهم، ويستفاد من النتائج والتقارير الدورية للتطوير والتحسين المستمر.', null, 30),
  ('pas', '3.1', '3', 'الدعم والتوجيه والإرشاد', 'تُقدم خدمات الدعم والتوجيه والإرشاد للمتدربين لرفع معدلات إكمالهم واستبقائهم، ويتم إجراء تقويم شامل لجودة وكفاية هذه الخدمات، ويستفاد من النتائج والتقارير الدورية للتطوير والتحسين المستمر.', null, 31),
  ('pas', '3.2', '3', 'الدعم المهني ومواءمة المهارات', 'يقدم البرنامج خدمات الدعم المهني المناسب للمتدربين لمواءمة مهاراتهم مع متطلبات سوق العمل، ويستفاد من النتائج والتقارير الدورية في تطوير وتحسين الخدمات.', null, 32),
  ('pas', '3.3', '3', 'المتميزون والمتعثرون وذوو الإعاقة', 'يُطبّق البرنامج آليات ملائمة للتعرف على المتدربين المتميزين والمتعثرين، والمتدربين من ذوي الإعاقة، ويوفر الخدمات المناسبة لرعايتهم وتحفيزهم ودعمهم، ويستفاد من النتائج والتقارير الدورية في تطوير الخدمات المقدمة.', null, 33),
  ('pas', '3.4', '3', 'الانتظام والمشاركة', 'يُطبّق البرنامج آليات لضمان انتظام المتدربين في الحضور والمشاركة الفاعلة في التدريب، وتتخذ الإجراءات التصحيحية اللازمة لذلك.', null, 34),
  ('pas', '3.5', '3', 'متابعة الخريجين', 'يُطبّق البرنامج آليات منتظمة للتواصل مع الخريجين، ومتابعة حصولهم على وظائف في مجال تخصصاتهم، ويحتفظ بقواعد بيانات محدثة وشاملة عنهم لخدمة مبادرات التوظيف الوطنية (بما في ذلك المرصد الوطني للعمل)، وتتخذ الإجراءات التصحيحية اللازمة لذلك.', null, 35),
  ('pas', '4', null, 'المدربون', 'تُطبق معايير محددة لاختيار الكوادر البشرية المؤهلة لتقديم البرنامج، وتتخذ الإجراءات اللازمة لاستبقائهم وتمكينهم من التطوير المهني لتعزيز جودة أدائهم، وتُتابع إجراءات التحسين والتطوير.', null, 40),
  ('pas', '4.1', '4', 'كفاية المدربين وخبرتهم', 'يتوافر في البرنامج العدد الكافي من المدربين المهنيين من ذوي الخبرة والمهارة والممارسة المهنية المناسبة في مجال البرنامج، وتوجد آليات مناسبة لمتابعة ذلك.', null, 41),
  ('pas', '4.2', '4', 'استبقاء المدربين', 'يُوجد منهجية فاعلة ومطبقة لاستبقاء المدربين، وتتخذ الإجراءات التصحيحية اللازمة لذلك.', null, 42),
  ('pas', '4.3', '4', 'التطوير المهني للمدربين', 'يُوجد منهجية فاعلة ومطبقة لتمكين المدربين من التطوير المهني المستمر للرفع من أدائهم وتأهيلهم وفق احتياجاتهم ومتطلبات البرنامج، وتتخذ الإجراءات التصحيحية اللازمة لذلك.', null, 43),
  ('pas', '4.4', '4', 'جودة أداء المدربين', 'يُطبّق البرنامج آليات منتظمة للتأكد من جودة أداء المدربين، وتطبيقهم لمنهجيات وإستراتيجيات التدريب المحددة في أدلة البرنامج (بما في ذلك دليل المدرب)، وتتخذ الإجراءات اللازمة للتحسين والتطوير.', null, 44),
  ('tps', 'A', null, 'القيم والمسؤوليات المهنية', 'القيم والمسؤوليات المهنية', 21, 100),
  ('tps', '1', 'A', 'الالتزام بالقيم الإسلامية الوسطية، وأخلاقيات المهنة، وتعزيز الهوية الوطنية', 'الالتزام بالقيم الإسلامية الوسطية، وأخلاقيات المهنة، وتعزيز الهوية الوطنية', null, 110),
  ('tps', '1.1', '1', 'الالتزام بالقيم الإسلامية الوسطية', 'الالتزام بالقيم الإسلامية الوسطية', null, 111),
  ('tps', '1.2', '1', 'تعزيز الهوية الوطنية والتنوع الثقافي', 'تعزيز الهوية الوطنية والتنوع الثقافي', null, 112),
  ('tps', '1.3', '1', 'الالتزام بالأنظمة واللوائح والسياسات التعليمية وأخلاقيات المهنة', 'الالتزام بالأنظمة واللوائح والسياسات التعليمية وأخلاقيات المهنة', null, 113),
  ('tps', '2', 'A', 'التطوير المهني المستمر', 'التطوير المهني المستمر', null, 120),
  ('tps', '2.1', '2', 'وضع خطة للتطوير المهني في ضوء المعايير المهنية', 'وضع خطة للتطوير المهني في ضوء المعايير المهنية', null, 121),
  ('tps', '2.2', '2', 'تطوير الأداء المهني في ضوء نتائج التقويم والتغذية الراجعة', 'تطوير الأداء المهني في ضوء نتائج التقويم والتغذية الراجعة', null, 122),
  ('tps', '3', 'A', 'التفاعل المهني مع التربويين والمجتمع', 'التفاعل المهني مع التربويين والمجتمع', null, 130),
  ('tps', '3.1', '3', 'التفاعل مع أسر الطلاب والمجتمع المحلي', 'التفاعل مع أسر الطلاب والمجتمع المحلي', null, 131),
  ('tps', '3.2', '3', 'التفاعل مع الزملاء والمجتمع المهني لتطوير الممارسات التعليمية', 'التفاعل مع الزملاء والمجتمع المهني لتطوير الممارسات التعليمية', null, 132),
  ('tps', 'B', null, 'المعرفة المهنية', 'المعرفة المهنية', 40, 200),
  ('tps', '4', 'B', 'الإلمام بالمهارات اللغوية والكمية', 'الإلمام بالمهارات اللغوية والكمية', null, 210),
  ('tps', '4.1', '4', 'الإلمام بالمهارات اللغوية (العربية) واستخداماتها في التواصل والتعليم', 'الإلمام بالمهارات اللغوية (العربية) واستخداماتها في التواصل والتعليم', null, 211),
  ('tps', '4.2', '4', 'الإلمام بالمهارات الكمية الأساسية واستخداماتها في التحليل والتفسير', 'الإلمام بالمهارات الكمية الأساسية واستخداماتها في التحليل والتفسير', null, 212),
  ('tps', '5', 'B', 'المعرفة بالطالب وكيفية تعلمه', 'المعرفة بالطالب وكيفية تعلمه', null, 220),
  ('tps', '5.1', '5', 'خصائص النمو البشري وتطبيقاتها في التعليم والتعلم', 'خصائص النمو البشري وتطبيقاتها في التعليم والتعلم', null, 221),
  ('tps', '5.2', '5', 'الفروق الفردية بين الطلاب وأساليب مراعاتها وتفريد التعليم', 'الفروق الفردية بين الطلاب وأساليب مراعاتها وتفريد التعليم', null, 222),
  ('tps', '5.3', '5', 'خصائص الطلاب ذوي الاحتياجات الخاصة واحتياجاتهم التعليمية', 'خصائص الطلاب ذوي الاحتياجات الخاصة واحتياجاتهم التعليمية', null, 223),
  ('tps', '6', 'B', 'المعرفة بمحتوى التخصص وطرق تدريسه', 'المعرفة بمحتوى التخصص وطرق تدريسه', null, 230),
  ('tps', '6.1', '6', 'الإلمام بمحتوى التخصص ومفاهيمه وبنيته المعرفية', 'الإلمام بمحتوى التخصص ومفاهيمه وبنيته المعرفية', null, 231),
  ('tps', '6.2', '6', 'الإلمام بطرق التدريس الخاصة بالتخصص وتطبيقاتها', 'الإلمام بطرق التدريس الخاصة بالتخصص وتطبيقاتها', null, 232),
  ('tps', '7', 'B', 'المعرفة بالمنهج وطرق التدريس العامة', 'المعرفة بالمنهج وطرق التدريس العامة', null, 240),
  ('tps', '7.1', '7', 'المعرفة بمفهوم المنهج ومكوناته وأسس بنائه وتقويمه', 'المعرفة بمفهوم المنهج ومكوناته وأسس بنائه وتقويمه', null, 241),
