  ('tps', '8.1', '8', 'التخطيط الفعال للدروس والوحدات الدراسية وتطويرها', 'التخطيط الفعال للدروس والوحدات الدراسية وتطويرها', null, 311),
  ('tps', '8.2', '8', 'تنفيذ التدريس وإدارة عمليات التعلم وتوظيف التقنيات بفاعلية', 'تنفيذ التدريس وإدارة عمليات التعلم وتوظيف التقنيات بفاعلية', null, 312),
  ('tps', '9', 'C', 'تهيئة بيئات تعلم تفاعلية وداعمة للطالب', 'تهيئة بيئات تعلم تفاعلية وداعمة للطالب', null, 320),
